-- Part 5: 30 câu hỏi hoàn chỉnh (101 - 130)
INSERT INTO question (question_number, content, option_a, option_b, option_c, option_d, correct_option, explanation, part_id) VALUES
(101, 'When she held her last meeting, Ms. Toba ------- her sales staff to perform even better next quarter.', 'encourage', 'is encouraging', 'encouraged', 'was encouraged', 'C', 'Hành động xảy ra trong quá khứ (\"held\"), chia thì quá khứ đơn chủ động.', 5),
(102, 'All staff have been informed ------- the proposed partnership with ERI Finance.', 'for', 'about', 'to', 'at', 'B', 'Cụm từ cố định: inform someone about/of something (thông báo về việc gì).', 5),
(103, 'On Friday, Mr. Nakamura will discuss ------- ideas for supporting busy waiters.', 'his', 'him', 'himself', 'he', 'A', 'Cần một tính từ sở hữu đứng trước danh từ \"ideas\".', 5),
(104, 'The Forestry Commission was created to ------- the state\'s natural resources and wildlife.', 'allow', 'manage', 'succeed', 'finish', 'B', 'Xét nghĩa: \"manage\" (quản lý tài nguyên thiên nhiên và động vật hoang dã).', 5),
(105, 'By following established guidelines, construction workers will be able to complete their tasks -------.', 'safety', 'safe', 'safeness', 'safely', 'D', 'Cần một trạng từ (safely) để bổ nghĩa cho động từ \"complete\".', 5),
(106, 'With her numerous credentials, Dr. Kwan is highly ------- to teach medieval history at Maston University.', 'arranged', 'ready', 'available', 'qualified', 'D', 'Cụm tính từ: highly qualified to do something (đủ trình độ/chuyên môn cao).', 5),
(107, '------- at the annual technology conference is mandatory for all engineers at the Treemont Corporation.', 'Attendance', 'Attend', 'Attends', 'Attended', 'A', 'Cần một danh từ (Attendance) đóng vai trò làm chủ ngữ của câu.', 5),
(108, 'The café ------- features poets, folk singers, and drama groups on its stage.', 'tightly', 'occasionally', 'vaguely', 'realistically', 'B', 'Xét nghĩa trạng từ chỉ tần suất: \"occasionally\" (thỉnh thoảng/đôi khi).', 5),
(109, 'Before the seminar began, attendees were assured ------- all scheduled presenters would appear.', 'who', 'around', 'that', 'therefore', 'C', 'Cấu trúc mệnh đề danh từ: be assured that + mệnh đề (được đảm bảo rằng).', 5),
(110, 'Forever Pet has been a leader in bringing new products, ------- Fun Bone and Chew Right, to the market.', 'however', 'furthermore', 'as if', 'such as', 'D', 'Dùng \"such as\" để đưa ra ví dụ minh họa.', 5),
(111, 'Ms. Turner is in charge of ------- the organization of records in the human services department.', 'improve', 'improved', 'improving', 'improvement', 'C', 'Sau giới từ \"of\" cần V-ing (\"improving\") vì phía sau có tân ngữ \"the organization\".', 5),
(112, 'Sheefon Bank clients always receive an e-mail or text ------- following any change to their account password.', 'issue', 'alert', 'claim', 'member', 'B', 'Cụm danh từ: \"text alert\" (thông báo/cảnh báo bằng tin nhắn văn bản).', 5),
(113, 'A drop in consumer demand has led to a ------- decrease in the production of large pickup trucks.', 'remark', 'remarked', 'remarking', 'remarkable', 'D', 'Cần tính từ \"remarkable\" (đáng kể) đứng trước danh từ \"decrease\".', 5),
(114, 'After coating the potatoes in flour and spices, chefs should place them ------- into the deep fryer.', 'rarely', 'honestly', 'doubtfully', 'directly', 'D', 'Xét nghĩa trạng từ: \"directly into\" (cho trực tiếp vào).', 5),
(115, 'Several banks have released applications that allow customers to pay bills ------- easily by phone.', 'their', 'they', 'them', 'themselves', 'D', 'Đại từ phản thân \"themselves\" dùng để nhấn mạnh khách hàng tự thanh toán hóa đơn.', 5),
(116, 'The personnel department will ------- only those applicants who have five or more years of experience for the position.', 'participate', 'consider', 'grant', 'make', 'B', 'Xét nghĩa ngoại động từ: \"consider\" (xem xét/cân nhắc các ứng viên).', 5),
(117, 'Employees of Belfore Electronics Ltd. are ------- involved in community-assistance programs.', 'active', 'actively', 'activate', 'activity', 'B', 'Cần trạng từ \"actively\" để bổ nghĩa cho tính từ/phân từ \"involved\".', 5),
(118, 'The executives at Macalter Equipment decided they would not ------- the contract without major changes.', 'renew', 'consume', 'identify', 'resemble', 'A', 'Cụm từ xét theo ngữ cảnh: \"renew the contract\" (gia hạn hợp đồng).', 5),
(119, 'Wet suits are made with a ------- layer of rubber that traps heat and keeps divers warm.', 'protect', 'protects', 'protective', 'protectively', 'C', 'Cần tính từ \"protective\" (bảo vệ) đứng trước danh từ \"layer\".', 5),
(120, 'Newcamp Services managers will meet to discuss the proposed ------- of three smaller branches into one large branch.', 'security', 'bracket', 'connector', 'merger', 'D', 'Xét nghĩa: \"merger\" (sự sáp nhập 3 chi nhánh nhỏ thành 1 chi nhánh lớn).', 5),
(121, 'At Yarzen Technology, clients\' records are ------- and can only be accessed by a small group of fund managers.', 'confide', 'confidential', 'confidentially', 'confidentiality', 'B', 'Sau động từ to-be \"are\" cần tính từ \"confidential\" (bảo mật).', 5),
(122, 'The featured panel at the NHJ Medical Conference will discuss recent ------- in online health-care services.', 'memories', 'varieties', 'trends', 'rehearsals', 'C', 'Xét nghĩa: \"recent trends\" (các xu hướng gần đây trong dịch vụ chăm sóc sức khỏe trực tuyến).', 5),
(123, 'All of Millville\'s restaurants ------- several times a year by the city health department.', 'inspect', 'inspected', 'are inspecting', 'are inspected', 'D', 'Câu bị động ở thì hiện tại đơn chỉ hành động lặp đi lặp lại: \"are inspected\".', 5),
(124, 'Sweet Sunlight Bakery has steadily built a ------- base of customers with its delicious cookies and cakes.', 'brief', 'loyal', 'strict', 'careful', 'B', 'Cụm từ phổ biến: \"loyal base of customers\" (tập khách hàng trung thành).', 5),
(125, 'According to financial analysts, ------- in medical technology companies are expected to increase in value.', 'invest', 'investing', 'invested', 'investments', 'D', 'Cần danh từ số nhiều \"investments\" (các khoản đầu tư) làm chủ ngữ cho động từ \"are\".', 5),
(126, 'The city\'s harbor is ------- to container ships and fishing vessels of all sizes.', 'accessible', 'formal', 'reasonable', 'likely', 'A', 'Cấu trúc: \"accessible to\" (có thể tiếp cận được đối với tàu thuyền mọi kích cỡ).', 5),
(127, 'Maya\'s Dancewear expanded its advertising markets, and sales have ------- increased.', 'controlling', 'consequently', 'beneath', 'even though', 'B', 'Trạng từ liên kết chỉ kết quả: \"consequently\" (kết quả là/do đó).', 5),
(128, 'Dobson Ice Cream will not introduce any new flavors ------- the customer survey results are analyzed.', 'around', 'until', 'despite', 'past', 'B', 'Cấu trúc: not... until (sẽ không giới thiệu hương vị mới cho đến khi kết quả được phân tích).', 5),
(129, 'The renovated company gym ------- with free weights and exercise machines.', 'will equip', 'to equip', 'has been equipped', 'is equipping', 'C', 'Dạng bị động hoàn thành: phòng tập \"đã được trang bị\" thiết bị tập luyện.', 5),
(130, '------- driving their cars, workers who travel to the town center should use the bus lines.', 'Because of', 'Instead of', 'Whenever', 'Although', 'B', 'Giới từ chỉ sự thay thế: \"Instead of + V-ing\" (thay vì lái xe ô tô).', 5);

-- Part 6: 4 Question Groups & 16 Câu hỏi hoàn chỉnh (131 - 146)
INSERT INTO question_group (id, part_id, passage_text) VALUES 
(1, 6, 'MALENDA COUNTY (January 12) - Pat and Kenny''s Barbershop, [131] at 3949 Grand Street, has been named the best barbershop in the state by the Barber and Hairdresser''s Coalition. The criteria for selection include reputation, affordability, professionalism, and accreditations. [132].\n\nFounders and owners Kenneth Webber and Patrick Miller have been best friends since childhood. [133] opened the shop 34 years ago. [134] the shop retains its old-fashioned charm, the barbers have mastered the latest styles, not just the more traditional ones. People of all ages seeking a haircut or a new style should try Pat and Kenny''s Barbershop.'),
(2, 6, 'Gasgo Propane Tank Exchange\n\nThank you for purchasing a Gasgo propane tank. You have chosen a safe and [135] way to obtain fuel for your stoves, grills, heaters, fireplaces, or other devices.\n\nSimply follow the directions [136]. When your tank runs out of propane, take it to our store and leave it on one of the clearly marked green shelves outside the store. [137] Then, pay the cashier inside the store for a fresh tank of propane.\n\nBe sure to visit us again when you need a [138].'),
(3, 6, 'To: Technicarn Enterprises Customers\nFrom: Customer Support\nDate: October 14\nSubject: New and Improved Web Site\n\nWe want your [139] with Technicarn Enterprises to be easy and enjoyable. We have recently redesigned our Web site to serve you better.\n\nOn our home page, you can get information about system setup, or you can troubleshoot by visiting [140] the Internet Issues or TV and Streaming Issues pages. [141], you can find detailed information concerning account management, access, billing, and payment.\n\n[142] Please explore the new Web site at your earliest convenience: www.technicarnenterprises.com.'),
(4, 6, 'Garner City Transport Cares About the Environment\n\nBeginning May 1, the sale and use of paper tickets and transit passes will be [143] on all Garner City Transport bus and subway lines. This change applies to single-ride tickets [144] weekly and monthly passes.\n\nGarner City Transport encourages riders to use the new mobile app. With the app, they can add money to their accounts, purchase tickets, plan [145], and track arrival and departure times.\n\nAlternatively, passengers can purchase a rechargeable transit card at any station. [146] Value can be added to the card via the Garner City Transport Web site at www.garnercitytransport.org.');

INSERT INTO question (question_number, content, option_a, option_b, option_c, option_d, correct_option, explanation, part_id, question_group_id) VALUES 
-- Đoạn 1 (131 - 134)
(131, 'Pat and Kenny\'s Barbershop, ------- at 3949 Grand Street, has been named the best barbershop in the state by the Barber and Hairdresser\'s Coalition.', 'locate', 'located', 'locates', 'location', 'B', 'Mệnh đề quan hệ rút gọn ở dạng bị động: \"which is located at...\" rút gọn thành \"located at...\".', 6, 1),
(132, 'The criteria for selection include reputation, affordability, professionalism, and accreditations. [-------]', 'The results will be announced later this month.', 'We are proud to serve our community with excellence.', 'Pat and Kenny\'s shop excelled in all four categories.', 'Please call in advance to schedule an appointment.', 'C', 'Câu phía trước nhắc đến 4 tiêu chí lựa chọn, do đó câu tiếp nối hợp lý nhất là khẳng định tiệm đã xuất sắc ở cả 4 tiêu chí đó.', 6, 1),
(133, 'Founders and owners Kenneth Webber and Patrick Miller have been best friends since childhood. ------- opened the shop 34 years ago.', 'I', 'We', 'They', 'He', 'C', 'Đại từ nhân xưng thay thế cho hai người đồng sáng lập (Kenneth Webber và Patrick Miller) là \"They\".', 6, 1),
(134, '------- the shop retains its old-fashioned charm, the barbers have mastered the latest styles, not just the more traditional ones.', 'While', 'Despite', 'Even', 'Yet', 'A', 'Dùng liên từ \"While\" (mặc dù) để chỉ sự tương phản giữa 2 mệnh đề: dù vẫn giữ nét cổ điển nhưng thợ cắt tóc đã làm chủ các phong cách mới nhất.', 6, 1),
-- Đoạn 2 (135 - 138)
(135, 'You have chosen a safe and ------- way to obtain fuel for your stoves, grills, heaters, fireplaces, or other devices.', 'economy', 'economics', 'economize', 'economical', 'D', 'Cần một tính từ song hành với \"safe\" đứng trước danh từ \"way\": \"economical\" (tiết kiệm/kinh tế).', 6, 2),
(136, 'Simply follow the directions -------.', 'below', 'finally', 'sometimes', 'hourly', 'A', 'Chỉ dẫn xuất hiện ở phần văn bản ngay phía dưới nên dùng trạng từ/giới từ chỉ vị trí: \"the directions below\" (hướng dẫn bên dưới).', 6, 2),
(137, 'When your tank runs out of propane, take it to our store and leave it on one of the clearly marked green shelves outside the store. [-------] Then, pay the cashier inside the store for a fresh tank of propane.', 'Come again very soon.', 'It is warmer in the store.', 'Do not take it inside.', 'The tank is prefilled.', 'C', 'Quy tắc an toàn khi đổi bình gas: để ở kệ bên ngoài cửa hàng và \"Không mang bình vào bên trong\" trước khi vào quầy thanh toán.', 6, 2),
(138, 'Be sure to visit us again when you need a -------.', 'model', 'version', 'heater', 'replacement', 'D', 'Ngữ cảnh đổi bình gas khi hết: ghé thăm lại khi bạn cần một bình thay thế (\"replacement\").', 6, 2),
-- Đoạn 3 (139 - 142)
(139, 'We want your ------- with Technicarn Enterprises to be easy and enjoyable.', 'experience', 'experienced', 'experiencing', 'experiential', 'A', 'Sau tính từ sở hữu \"your\" cần một danh từ: \"experience\" (trải nghiệm của bạn).', 6, 3),
(140, 'On our home page, you can get information about system setup, or you can troubleshoot by visiting ------- the Internet Issues or TV and Streaming Issues pages.', 'either', 'both', 'rather', 'each', 'A', 'Cấu trúc tương quan đi kèm với liên từ \"or\": \"either A or B\".', 6, 3),
(141, '-------, you can find detailed information concerning account management, access, billing, and payment.', 'Therefore', 'Regardless', 'For example', 'Moreover', 'D', 'Trạng từ liên kết bổ sung thông tin thêm về các tiện ích trên trang web: \"Moreover\" (Hơn thế nữa/Ngoài ra).', 6, 3),
(142, '[-------] Please explore the new Web site at your earliest convenience: www.technicarnenterprises.com.', 'We also need to inform you that your payment is five days past due.', 'We recommend that you purchase all related accessories in our retail store.', 'If you get an error message, disconnect from the Internet and try again.', 'If you cannot find what you need online, simply call our support number.', 'D', 'Đoạn văn giới thiệu các tiện ích trực tuyến, câu kết cung cấp phương án hỗ trợ dự phòng: nếu không tìm thấy trên mạng hãy gọi tổng đài.', 6, 3),
-- Đoạn 4 (143 - 146)
(143, 'Beginning May 1, the sale and use of paper tickets and transit passes will be ------- on all Garner City Transport bus and subway lines.', 'enlarged', 'discontinued', 'accessible', 'refreshed', 'B', 'Xét theo ngữ cảnh bảo vệ môi trường và chuyển sang ứng dụng/thẻ: vé giấy sẽ bị \"ngừng sử dụng\" (discontinued).', 6, 4),
(144, 'This change applies to single-ride tickets ------- weekly and monthly passes.', 'sharing', 'but', 'except', 'as well as', 'D', 'Cụm liên từ mang nghĩa \"cũng như\": \"as well as\" nối vé 1 lượt với vé tuần/tháng.', 6, 4),
(145, 'With the app, they can add money to their accounts, purchase tickets, plan -------, and track arrival and departure times.', 'routes', 'responses', 'software', 'careers', 'A', 'Xét chức năng của ứng dụng giao thông công cộng: \"plan routes\" (lên kế hoạch tuyến đường).', 6, 4),
(146, 'Alternatively, passengers can purchase a rechargeable transit card at any station. [-------] Value can be added to the card via the Garner City Transport Web site at www.garnercitytransport.org.', 'People often use credit cards to purchase meals during the flight.', 'Many people like public transportation because it is inexpensive.', 'The durable cards are made from recycled materials.', 'There was a small price increase last month.', 'C', 'Câu đứng giữa mô tả thêm đặc tính của thẻ giao thông sạc lại được (\"rechargeable transit card\") và phù hợp tiêu chí môi trường: thẻ bền và làm từ vật liệu tái chế.', 6, 4);

-- Part 7: 15 Question Groups & 54 Câu hỏi hoàn chỉnh (147 - 200)
INSERT INTO question_group (id, part_id, passage_text) VALUES 
-- Đoạn 1: Questions 147-148 (Advertisement)
(5, 7, 'Harbis Stationery Store Clearance Sale\n\nPrices indicated are for in-store purchases only.\n\n500 Pinstone Street / SHEFFIELD / S1 2HN\n\nSeasonal items\nBox of ten preprinted seasonal cards (25% off) - £ 8.99\nBox of five customizable seasonal cards or invitations (50% off) - £ 11.99\n\nAll school supplies 10% off\nBox of 24 pens - £ 1.79\nDesk lamp - £ 19.99\nWireless mouse - £ 17.99\nBackpack - £ 29.99\n\nVisit Harbis Stationery at www.harbisstationery.uk'),
-- Đoạn 2: Questions 149-150 (E-mail)
(6, 7, 'To: Wenbin Peng <wpeng@chenconstruction.com>\nFrom: Toshi Auto Group <cs@toshiautogroup.com>\nDate: February 26\nSubject: Your leased vehicle\n\nDear Mr. Peng:\nAs you know, Toshi Auto Group handles all the service needs for cars leased by employees of Chen Construction. According to our records, you took possession of your leased car on March 1 of last year. Your car is now due for its required annual service and maintenance check. To book your appointment, please call us at (215) 555-0109 or visit us online at www.toshiautogroup.com/serviceappointments.\n\nSincerely,\nToshi Auto Group\nCustomer Service'),
-- Đoạn 3: Questions 151-153 (Article)
(7, 7, 'LONDON (2 February) On Thursday, Tillford Press announced the launch of its new imprint, Tillford Exalt. This new line will feature books promoting healthy lifestyles, memoirs with uplifting messages, and volumes that provide guidance for special occasions such as birthdays and weddings. Tillford Exalt will also publish calendars and greeting cards that complement the main products.\n\nAlready contracted to write memoirs are the award-winning actress Alexia Leoz, London-based conductor and composer Seung-Hyun Bae, and celebrity cook Lain Lai. Ms. Lai\'s story of her life and career will be the first to be launched. It is set for release in December.\n\nTillford vice president Frederick Bissett said the company saw a need for books that celebrated accomplishments and life events from multiple perspectives. "We wanted authors from a wide variety of cultural backgrounds, and we think we\'re off to a great start," he said. He noted that Tillford Exalt\'s authors were not always famous; the books will be exploring their beginnings, their everyday lives, their first jobs, their marriages and families as well as their achievements.\n\nTillford Press is based in Manchester. It has offices in New York, Toronto, and Sydney, but its publications are sold throughout the world.'),
-- Đoạn 4: Questions 154-155 (Text-message chain)
(8, 7, 'Greg Skagen (8:58 A.M.) Hi, Brenda. I\'m here in the warehouse. All of my trainees have arrived, but I noticed the power door at Loading Dock B is acting up.\nBrenda Sadauskas (8:59 A.M.) Again?\nGreg Skagen (8:59 A.M.) When I push the button to open it, it raises all the way up but then drops back down to the closed position after about 30 seconds.\nBrenda Sadauskas (9:00 A.M.) I\'ll come down with the maintenance technicians. Why don\'t you bring your trainees to my area? You can teach them how to create shipping labels and then have them pack and label this morning\'s shipments.\nGreg Skagen (9:02 A.M.) Yes, that works.\nBrenda Sadauskas (9:03 A.M.) Thanks. Then you could show them the loading dock operations in the afternoon.'),
-- Đoạn 5: Questions 156-157 (Form)
(9, 7, 'SERVICE REQUEST FORM\nComplete all fields and deliver to Technology Services (room 412).\n\nRequester Name: Elenora Deckow\nRequester Office: Room 718\nRequester Phone: Ext. 5709\nService Location: Room 500\nService Type (choose one): [X] Repair\n\nDescription of Request:\nThere is a problem with the television audio. When I played an online video, the image was fine, but I could not hear anything. I checked all the settings, and I was able to hear the same video on other televisions with no problem. I\'m supposed to deliver a product demonstration for a client in room 500 next Monday, so I would greatly appreciate it if the issue can be fixed by this Friday.'),
-- Đoạn 6: Questions 158-161 (Text-message chain)
(10, 7, 'Ella Glatt (11:34 A.M.)\nHi. I know this is a busy day, but I wanted to know whether anyone from the finance team could come to the marketing meeting.\n\nStef Goldberg (11:35 A.M.)\nHi, Ella. I wish I could, but it starts at 2:00. I need to be at a different meeting at 2:30.\n\nElla Glatt (11:36 A.M.)\nOh, right. I forgot you were going to the executive board meeting.\n\nDaniel Seidal (11:36 A.M.)\nI\'m also supposed to go to the 2:30 meeting. Is it essential that one of us attend the marketing meeting?\n\nElla Glatt (11:37 A.M.)\nWell, it would be helpful to have someone from the finance department there, at least for 15 minutes or so.\n\nBill Iverman (11:38 A.M.)\nThe quarterly reports just came in, and Daniel, Stef, and I need to review them by the end of the day.\n\nElla Glatt (11:39 A.M.)\nYou all have plenty to do.\n\nDaniel Seidal (11:41 A.M.)\nThat\'s true! But I could come from 2:00 to 2:15. That\'s all I can commit to.\n\nElla Glatt (11:43 A.M.)\nSounds great. We just need one of you to clarify a few quick points about the budget for the next advertising campaign.'),
-- Đoạn 7: Questions 162-165 (E-mail)
(11, 7, 'To: amal.abboud@bunzifoundation.org\nFrom: maria_mcfarland@myemail.com\nDate: Thursday, August 22\nSubject: Project Coordinator Position\nAttachment: résumé_m.mcfarland.pdf\n\nDear Mr. Abboud,\nMy friend Josiah Wilkins told me that you are seeking a project coordinator for your company. I have a degree in business administration and am attaching my résumé as I think I am an excellent fit for your needs. As you will see, I have experience using several cloud-based project-management programs. Furthermore, my organizational skills enable me to coordinate multiple activities simultaneously, and I can convey expectations clearly to team members involved in each phase of a project.\n\nMy current role as project coordinator for an international engineering firm, where I have worked for the past five years, has also afforded me ample experience managing teams, schedules, and budgets. While I enjoy the kind of work I do, it has become clear to me that I need motivation from a strong mission. The goal of your company to create sustainable housing projects is something that I strongly support and would be delighted to work on.\n\nThrough my work and volunteer activities, I have spent many months abroad in various countries throughout Asia and the Middle East. This seems particularly relevant to mention, as I am comfortable leading geographically and culturally diverse teams.\n\nThank you for your attention, and I look forward to speaking with you soon.\n\nKind regards,\nMaria McFarland'),
-- Đoạn 8: Questions 166-168 (Web page)
(12, 7, 'https://trexdale.com/aboutus\n\nAbout Our Company\n\nTrexdale Supply specializes in designing, producing, and installing furniture for all types of scientific laboratories. We provide a range of fully assembled cabinets, workstations, benches, and more, all made exclusively at our production facility in Dallas, Texas. Our lab furniture is available in a wide variety of sizes and configurations to match the needs of any research application.\n\nOur business offers products as well as design-consulting services. For start-up labs, we have a team of consulting specialists available to evaluate your facility\'s specific needs and assist you in arranging your space and choosing the most suitable furniture. Recently, for example, we were chosen by a major producer of biofuels to provide expert help in changing the layout of a research laboratory to maximize available space. As a result of this project, this client has realized substantial savings by reducing energy usage in the lab.\n\nPlease visit the "Lab Planning" section of this Web site if you are interested in learning more about building or renovating a laboratory facility. There, you can fill out an interest form to contact one of our consultants about your next project.'),
-- Đoạn 9: Questions 169-171 (Job advertisement)
(13, 7, 'PRODUCT DEMONSTRATORS NEEDED!\n\nAre you outgoing and enthusiastic? - [1] -. Do you enjoy talking to all types of people? Put your personality and communication skills to work! - [2] -. BBD Staffing is seeking to hire in-store product demonstrators to promote our clients\' merchandise to shoppers. - [3] -. As a member of our team, you will demonstrate a wide range of small kitchen appliances and tools in grocery stores and other retail venues.\n\nFor some products, you will be required to prepare simple recipes. You will also need to answer shoppers\' questions. Thus, it is essential that you can become familiar with clients\' products and provide key information to consumers. Because many of the demonstrations require working with food, candidates must have a Professional Food Handler certificate. - [4] -.\n\nTo apply, upload a video of no more than one minute in length telling us why you would be a successful product demonstrator at www.bbdstaffing.com/applications.'),
-- Đoạn 10: Questions 172-175 (Article)
(14, 7, 'Gorman Unveils Newest Smartphone Model\n\nLONDON (20 April) - Gorman Mobile unveiled its newest smartphone to an eager reception at the annual Technobrit Conference. The Pro Phone 4, which includes 512 GB of storage, a 7-inch screen display, and an optional stylus pen, will hit the shelves on 11 June. Unlike its predecessor - the Pro Phone 3 - it features a larger screen, an ultrawide camera lens, and 8K-resolution filming capability. - [1] -. The £999 starting price is £100 more than that of the previous model. Add-ons, such as the stylus pen, protective case, and wireless headphones, cost an additional £39, £59, and £79, respectively. Gorman Product Manager Ian Hill doesn\'t believe the price increase will dissuade customers. - [2] -.\n\n"The Pro Phone 4 is a game changer in terms of its picture quality and sleek design," said Hill. "Improvements were based on direct customer feedback, which cited the poor camera functionality as the biggest drawback of prior models. Our clients spoke, and we listened and adapted accordingly." - [3] -.\n\nOne similarity that the Pro Phone 4 has with previous models is the charger. Going against the trend of competing wireless companies, Gorman is instead focusing on convenience.\n\n"We want to afford our customers the ability to reuse elements of the other Gorman devices they\'ve already purchased," said Hill. "Why add to the overload of cables already in circulation?" - [4] -.'),
-- Đoạn 11: Questions 176-180 (Double Passage)
(15, 7, 'WORK ORDER: 7549\nRequester: Xi, Gina\nDate Entered: Wednesday, 9 April\nDate Due: Thursday, 10 April\nType: Technology end-user request\nSummary: Voice-mail security settings\nTechnician Assigned: Arnold, Sam\nComputer Workstation ID: HYS31\nDescription: Is it possible to remove the new layers of security on my voice mail in the new phone system? I really don\'t want to use a password, and I certainly don\'t want to change it every month. I don\'t need a high degree of security because my work is not confidential. If someone else gained access to my messages, it wouldn\'t do much harm.\n\n---\n\nTo: Gina Xi\nFrom: Sam Arnold\nDate: Thursday, 10 April\nSubject: Tech support request 7549\n\nHello, Ms. Xi,\nThis is in reference to your work order 7549 related to the new phone system. I am happy to help you with that. I understand that you do not feel that a high degree of security is needed for your voice-mail settings, but the new system does require you to have a password to retrieve your voice mail. However, company policy allows me to change the settings for employees who do not work with confidential material. I can update the security settings so that you do not have to reset the password on a regular basis.\n\nI want to make sure that you understand the risk involved with a lower level of security. Anyone who gains access to your voice-mail account can do more than simply listen to your messages. They would be able to delete messages, change your greeting, or change your password so that you would lose access to your own voice mail (at least until someone here at IT could override the password change). If you still feel comfortable with that level of risk, let me know, and I will change the settings so that your password never expires.\n\nSam Arnold\nTech Support Associate'),
-- Đoạn 12: Questions 181-185 (Double Passage)
(16, 7, 'To: Linda Hanshu\nFrom: Cliff Merson\nSubject: Lighting Issue\nDate: September 4, 10:12 A.M.\n\nHi, Ms. Hanshu:\nI want to check on the issue we discussed about lighting in the latest chapter of Titan Adventure. In past versions of the game, getting the reflections and lighting in green and blue areas correct has been a particular challenge, and it was a problem that kept arising. As the new release, Neptune\'s Voyage, is primarily an underwater adventure, addressing this problem is crucial. You said you would take charge of this, and I hope to hear that you have found a solution to the problem. The team was hoping to have one last rendering of the lighting for the game by October 10 for a preliminary run-through. Will the final version of the lighting be ready by then?\n\nAll other aspects of the game are on schedule. Please send me an update about the lighting at your earliest convenience.\n\nRegards,\nCliff Merson\nProject Manager, Rimerko Games\n\n---\n\nReview of Titan Adventure: Neptune\'s Voyage\nBy Leo Weber, April 1\n\nThis new installment of Titan Adventure will surprise and delight both new players and old aficionados long familiar with the series. Though open-world formats have been widespread in recent years, Neptune\'s Voyage brings something new to the format. By stripping down instructional guides, the game gives users the opportunity to discover new areas and devices. In Neptune\'s Voyage, you wake up as Thetis, a dolphin that is tasked with rescuing Neptune from an underwater cave. Users then climb, run, ride, sail, and fly through the world of the game, encountering new towns, ruins, and other creatures along the way. Some of these creatures will be familiar to longtime fans, but there is plenty of novelty as well. This newest version also corrects the green and blue image rendering that was sometimes a problem in earlier installments of Titan Adventure.\n\nNeptune\'s Voyage launches May 5 on Rimerko Clutch and FS5. It is available in English, Korean, Japanese, French, and Spanish.'),
-- Đoạn 13: Questions 186-190 (Triple Passage)
(17, 7, 'Wonder Ridge Radio Broadcast Schedule, Monday-Friday\n\n• 6 A.M.-Noon: COFFEE BREAK (Local news and interviews with community members) | Host: Felice Finney\n• Noon-4 P.M.: AFTERNOON JAZZ (Music from traditional jazz to jazz fusion) | Host: Malachi Mzee\n• 4 P.M.-7 P.M.: FOLK FRENZY (Folk music from around the world) | Host: Penny Ariza\n• 7 P.M.-10 P.M.: JOSIE\'S JOINT (Modern sounds selected by our station\'s own music director) | Host: Josie Jones\n\n---\n\nTo: feedback@wonderridgeradio.org\nFrom: pfabre@sendmail.net\nSubject: My new radio station!\nDate: October 22\n\nTo the folks at Wonder Ridge Radio:\nAs I was driving last week, I got tired of listening to sports talk and turned the dial. Suddenly, my car was filled with a song that I hadn\'t heard in many years. It was traditional music from France, where my grandmother was born. She used to play that song when I was a child. I never expected to hear it on the radio here in Wonder Ridge. Thanks for this experience and for all your great programs.\n\nYour new fan,\nPierre Fabre\n\n---\n\nWonder Ridge Radio Job Opening: Programming Assistant\nPosted November 2\n\nJob Description\nThe programming assistant reports to the director of programming and supports the radio station by performing a variety of research and communication functions. This role is an entry-level, part-time position.\n\nResponsibilities\n• Conducting background research on interviewees\n• Keeping up-to-date on news and news makers in order to suggest potential topics and guests for on-air interviews\n• Updating the station\'s Web site and program host biography pages\n• Using scheduling software to update the broadcast schedule\n• Communicating with listeners, especially via e-mail and social media\n\nTo apply, e-mail a résumé and cover letter to hiring@wonderridgeradio.org.'),
-- Đoạn 14: Questions 191-195 (Triple Passage)
(18, 7, 'Instructions for Requesting Records\nThank you for your interest in official records and documents maintained by the City of Abilene. To file a request for public information, please follow these steps.\n1. Create an account in the Records Center Web portal. Currently, all requests must be made through the portal.\n2. Use the drop-down menu to locate the department from which you are seeking information and submit your request. You will receive a confirmation e-mail with a reference number.\n3. The department staff will locate the requested records and contact you when they are available. You can have the records delivered to you, or you can pick them up in person. If you prefer to pick them up in person, you must make an appointment with the department staff.\n4. If there are any fees associated with your request, you will receive an itemized statement detailing the services provided and the charges for those specific services.\n\n---\n\nTo: Joo-Hee Park <jhpark@coa.net>\nFrom: Keith Brandenberg <kbrandenberg@mailcurrent.com>\nDate: May 3\nSubject: RE: Reference number W2486\n\nDear Ms. Park,\nThank you for confirming that my documents are available. I would like to pick them up in person as soon as possible. Do you have any appointments available this week?\n\nI have a question about the fee. Apparently, I am being charged $300 for my documents. I do not understand why the fee is so high, and there was no explanation included in your e-mail. I have requested records several times in the past in my role with RJ Environmental Engineering and have never paid such a high fee. In this case, I am only requesting two maps of the city\'s underground pipelines, which will inform our firm\'s current work advising the city on wastewater management.\n\nPlease clarify the fee for me, and let me know if I can pick up my documents this week. Thank you.\n\nBest regards,\nKeith Brandenberg\n\n---\n\nCity of Abilene Administrative Building\nVisitors must sign in prior to entering this facility. Please enter your name and the room you will visit in the logbook.\n\nFirst-Floor Directory:\nIT Services - Room 100\nParks and Recreation - Room 101\nTransportation - Room 102\nWastewater - Room 103'),
-- Đoạn 15: Questions 196-200 (Triple Passage)
(19, 7, 'Famous Actor, First Book\n\nLONDON (25 February) - Fans of Simon Eklund will be delighted with his autobiography, The Theatre Lights Dimmed, the first book he has written in his storied career as an actor. It provides wonderful insight into his career, starting with his first roles in cinema in his native Sweden, moving into his work in France and Italy, and finishing with his recent theatre work in the U.K.\n\nIn his book, Mr. Eklund dedicates a fair amount of text to discussing his mentor, Charles Gunnarsson, who helped him develop his skills early on in Stockholm. He also describes the difficulty of transitioning into different types of roles, especially from comedic to dramatic acting. He includes several funny anecdotes about his first attempts at acting onstage here in London. He describes them as disastrous, but anyone who saw his recent performance in Life and Games would say just the opposite.\n\nMr. Eklund has long been a captivating actor on stage and screen, and now he is a thoroughly engaging author.\n—Uma Joshi\n\n---\n\nTo: Edith Hocking\nFrom: Uma Joshi\nDate: 2 March\nSubject: RE: Opportunity\n\nDear Edith,\nThank you for agreeing to arrange an interview with Mr. Eklund for me. I think this will be a great follow-up to my recent piece.\n\nIn a helpful coincidence, I will be visiting his home country next month to address a journalists\' convention. I am the featured speaker and will discuss the benefits of diversity in journalism. I\'m sure we can set up something with Mr. Eklund just before or after my speech.\n\nBest,\nUma Joshi\nArts and Culture Editor\nTop News U.K.\n\n---\n\nTo: Uma Joshi <ujoshi@topnews.co.uk>\nFrom: Maria Cazalla <mcazalla@zephyrmail.se>\nDate: 20 March\nSubject: RE: Information\n\nDear Ms. Joshi,\nWe are all very excited about your interview next month with Mr. Eklund. He enjoys all your writing for Top News U.K.—the news stories, interviews, and, of course, your recent article about The Theatre Lights Dimmed!\n\nI just wanted to finalize a few details with you. We have arranged transportation for you from your hotel to Mr. Eklund\'s house and then back to the hotel. Please let me know how many people there will be in your group, because Mr. Eklund would like you all to stay for lunch.\n\nSincerely,\nMaria Cazalla');

